-- ************************************** [consumption].[vw_SalesOrderAnalysis]
CREATE VIEW [consumption].[vw_SalesOrderAnalysis] AS
SELECT 
    so.SalesOrderId,
    so.OrderNumber,
    so.CustomerId,
    c.CustomerName,
    so.OrderDate,
    so.CurrencyCode,
    so.Status,
    COUNT(DISTINCT sol.SalesOrderLineId) AS LineItemCount,
    SUM(sol.Quantity * sol.UnitPrice * (1 - sol.DiscountPct / 100)) AS GrossAmount,
    SUM(sol.Quantity * sol.UnitPrice * (1 - sol.DiscountPct / 100) * sol.TaxPct / 100) AS TotalTax,
    SUM(sol.Quantity * sol.UnitPrice * (1 - sol.DiscountPct / 100) * (1 + sol.TaxPct / 100)) AS NetAmount,
    so.CreatedAt,
    so.UpdatedAt
FROM dbo.SalesOrder so
INNER JOIN dbo.Customer c ON so.CustomerId = c.CustomerId
LEFT JOIN dbo.SalesOrderLine sol ON so.SalesOrderId = sol.SalesOrderId
GROUP BY 
    so.SalesOrderId, so.OrderNumber, so.CustomerId, c.CustomerName,
    so.OrderDate, so.CurrencyCode, so.Status, so.CreatedAt, so.UpdatedAt;
GO
